"""Real offline FFmpeg integration tests, with synthetic media only."""
import json
import base64
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'tools'))
import local_factory as f
import project_to_bundle as converter


def fixture(root, count=3, seconds=3, job_id='test_job_001'):
    root = Path(root)
    # PNG generated by FFmpeg's official lavfi source, no image generation API.
    subprocess.run(['ffmpeg', '-v', 'error', '-f', 'lavfi', '-i', 'color=red:s=320x180',
                    '-frames:v', '1', '-threads', '1', str(root / 'red.png')], check=True)
    subprocess.run(['ffmpeg', '-v', 'error', '-f', 'lavfi', '-i', 'sine=frequency=440:sample_rate=24000',
                    '-t', str(seconds), str(root / 'tone.wav')], check=True)
    image = {'path': 'red.png', 'sha256': f.digest(root / 'red.png')}
    manifest = {'format': 'video-factory-render/v1', 'id': job_id, 'channel': 'life-ranges-es',
                'material': 'synthetic', 'alignment': {'source': 'synthetic-known-times', 'reviewed': False},
                'audio': {'path': 'tone.wav', 'sha256': f.digest(root / 'tone.wav')},
                'scenes': [{'id': f's{i+1:03}', 'start': i*seconds/count, 'end': (i+1)*seconds/count,
                            'prompt': f'Synthetic red scene {i+1}', 'narration': f'Synthetic scene {i+1}',
                            'sourcePromptId': str(i+1), 'image': image} for i in range(count)],
                'cues': [{'start': 0, 'end': seconds, 'text': 'Test subtitles áé ñ {no override}'}],
                'clips': [{'start': 0, 'end': seconds, 'title': 'Synthetic clip'}]}
    path = root / 'render.json'
    f.atomic_json(path, manifest)
    return path, manifest


class FactoryTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix='autovideo-test-')
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.path, self.manifest = fixture(self.root)

    def test_queue_checkpoint_recovery_and_real_mp4(self):
        db, out = self.root/'jobs.sqlite', self.root/'out'
        self.assertFalse(f.enqueue(db, self.path)['existing'])
        self.assertTrue(f.enqueue(db, self.path)['existing'])
        with self.assertRaisesRegex(RuntimeError, 'Controlled interruption'):
            f.work_once(db, out, burn=True, stop_after=2)
        with f.connect(db) as conn:
            row = conn.execute('SELECT * FROM jobs').fetchone()
            self.assertEqual((row['state'], row['attempts']), ('failed', 1))
            conn.execute("UPDATE jobs SET state='queued' WHERE id=?", (self.manifest['id'],))
        result = f.work_once(db, out, burn=True)
        self.assertEqual((result['reusedSegments'], result['renderedSegments']), (2, 1))
        info = f.probe(result['master'])
        self.assertEqual([s['codec_name'] for s in info['streams']], ['h264', 'aac'])
        self.assertAlmostEqual(float(info['format']['duration']), 3, delta=.15)
        handoff = json.loads(Path(result['master']).with_name('master.clipfarming.json').read_text())
        subprocess.run(['node', '-e', "require('./automation/media-contract.js').validateHandoff(JSON.parse(require('fs').readFileSync(process.argv[1])))", str(Path(result['master']).with_name('master.clipfarming.json'))], cwd=Path(__file__).resolve().parents[1], check=True)
        self.assertEqual(handoff['video']['sha256'], f.digest(result['master']))
        with f.connect(db) as conn:
            self.assertEqual(conn.execute('SELECT state FROM jobs').fetchone()[0], 'review')
        self.assertIsNone(f.work_once(db, out))
        # A damaged completed fragment must be regenerated, not silently reused.
        segment = Path(result['master']).parent / '0001' / 'segment.mp4'
        segment.write_bytes(b'broken')
        repaired = f.render(self.path, out, burn=True)
        self.assertEqual((repaired['reusedSegments'], repaired['renderedSegments']), (2, 1))

    def test_fail_closed_on_changed_inputs_and_unreviewed_real_alignment(self):
        f.validate(self.manifest, self.root)
        self.manifest['material'] = 'real'
        with self.assertRaisesRegex(ValueError, 'reviewed alignment'):
            f.validate(self.manifest, self.root)
        self.manifest['material'] = 'synthetic'
        db = self.root/'jobs.sqlite'
        f.enqueue(db, self.path)
        self.manifest['scenes'][0]['prompt'] = 'Changed after enqueue'
        f.atomic_json(self.path, self.manifest)
        with self.assertRaisesRegex(ValueError, 'different content'):
            f.enqueue(db, self.path)
        with self.assertRaisesRegex(ValueError, 'modified'):
            f.work_once(db, self.root/'out')
        self.manifest['scenes'][0]['image']['path'] = '../escape.png'
        with self.assertRaisesRegex(ValueError, 'outside bundle'):
            f.validate(self.manifest, self.root)

    def test_expired_lease_and_all_channels(self):
        for channel in ['life-ranges-es', 'life-ranges-en', 'finance-es', 'finance-en']:
            self.manifest['channel'] = channel
            f.validate(self.manifest, self.root)
        db = self.root/'jobs.sqlite'
        f.enqueue(db, self.path)
        with f.connect(db) as conn:
            conn.execute("UPDATE jobs SET state='running',owner='dead',lease=0")
        self.assertIsNone(f.work_once(db, self.root/'out'))
        with f.connect(db) as conn:
            self.assertEqual(conn.execute('SELECT state FROM jobs').fetchone()[0], 'failed')
            conn.execute("UPDATE jobs SET state='running',owner='live',lease=9999999999")
        self.assertIsNone(f.work_once(db, self.root/'out'))

    def test_project_conversion_preserves_assets_and_refuses_estimated_real_timings(self):
        image = 'data:image/png;base64,'+base64.b64encode((self.root/'red.png').read_bytes()).decode()
        audio = 'data:audio/wav;base64,'+base64.b64encode((self.root/'tone.wav').read_bytes()).decode()
        job = {'id': 'convert_test_001', 'niche': 'finance', 'language': 'en', 'scenes': []}
        project = {'type': 'FacelessStudioProject', 'version': 1, 'factoryJob': job, 'duration': 3,
                   'voice': {'name': 'tone.wav', 'data': audio}, 'scenes': [], 'images': [], 'verified': False}
        for i in range(3):
            text, prompt = f'Synthetic scene {i+1}', f'Prompt {i+1}'
            job['scenes'].append({'narration': text, 'imagePrompt': prompt})
            project['images'].append({'url': image, 'prompt': prompt, 'sceneIndex': i, 'name': f'{i+1:04}.png'})
            project['scenes'].append({'text': text, 'imgIndex': i, 'start': i, 'end': i+1,
                                      'timingSource': 'estimated', 'wordTimings': [{'start': i+j/3, 'end': i+(j+1)/3} for j in range(3)]})
        path = self.root/'project.avfproject'
        f.atomic_json(path, project)
        with self.assertRaisesRegex(ValueError, 'recognized timings'):
            converter.convert(path, self.root/'real', 'finance-en', 'real', True)
        output = converter.convert(path, self.root/'bundle', 'finance-en', 'synthetic')
        manifest = json.loads(output.read_text())
        self.assertEqual(len(manifest['scenes']), 3)
        self.assertEqual(len(manifest['cues']), 3)
        self.assertEqual(manifest['audio']['sha256'], f.digest(self.root/'tone.wav'))
        self.assertEqual(f.validate(manifest, output.parent), 3)
        with self.assertRaises(FileExistsError):
            converter.convert(path, self.root/'bundle', 'finance-en', 'synthetic')
        inbox = self.root/'inbox'
        inbox.mkdir()
        converter.convert(path, inbox/'one', 'finance-en', 'synthetic')
        db = self.root/'scan.sqlite'
        self.assertFalse(f.scan(db, inbox)[0]['existing'])
        self.assertTrue(f.scan(db, inbox)[0]['existing'])


if __name__ == '__main__':
    unittest.main()
